FROM attachments
WHERE user_id = #{userId}

    AND (original_name LIKE CONCAT('%', #{keyword}, '%') OR remark LIKE CONCAT('%', #{keyword}, '%'))


    AND source = #{source}


    AND (tags = #{tag} OR tags LIKE CONCAT(#{tag}, ',%') OR tags LIKE CONCAT('%,', #{tag}, ',%') OR tags LIKE CONCAT('%,', #{tag}))


